import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

import '../../core/app_info.dart';
import '../../core/app_scope.dart';
import '../../core/bank_rules.dart';
import '../legal/legal_document.dart';
import '../widgets/adaptive.dart';

/// Guía de uso y acerca de.
class GuideScreen extends StatelessWidget {
  const GuideScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final bool es = AppScope.of(context).settings.spanish;
    final List<_Section> sections = _sections(es);
    return ReadableScaffold(
      appBar: AppBar(title: Text(t(context, 'Guía', 'Guide'))),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 32),
        children: <Widget>[
          for (final _Section sec in sections)
            ExpansionTile(
              tilePadding: EdgeInsets.zero,
              childrenPadding: const EdgeInsets.only(bottom: 12),
              leading: Icon(sec.icon),
              title: Text(sec.title, style: const TextStyle(fontWeight: FontWeight.w600)),
              children: <Widget>[Align(alignment: Alignment.centerLeft, child: Text(sec.body))],
            ),
          const Divider(height: 32),
          Text(t(context, 'Acerca de Plata', 'About Plata'), style: Theme.of(context).textTheme.titleMedium),
          const SizedBox(height: 6),
          Text(t(
            context,
            'Versión $kAppVersion. Gratis, sin anuncios, sin cuenta y sin servidores: tus datos viven cifrados solo en tu teléfono. La única conexión que hace la app es descargar tasas de cambio (TRM de datos.gov.co, Banco Central Europeo vía Frankfurter y ExchangeRate-API), y puedes apagarla.',
            'Version $kAppVersion. Free, no ads, no account and no servers: your data lives encrypted only on your phone. The only connection the app makes is to download exchange rates (TRM from datos.gov.co, the European Central Bank via Frankfurter, and ExchangeRate-API), and you can turn it off.',
          )),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: <Widget>[
              OutlinedButton.icon(onPressed: () => launchUrl(Uri.parse(kRepoUrl), mode: LaunchMode.externalApplication), icon: const Icon(Icons.code), label: Text(t(context, 'Código fuente', 'Source code'))),
              OutlinedButton.icon(onPressed: () => launchUrl(Uri.parse(kIssuesUrl), mode: LaunchMode.externalApplication), icon: const Icon(Icons.bug_report_outlined), label: Text(t(context, 'Reportar un problema', 'Report a problem'))),
              OutlinedButton.icon(onPressed: () => Navigator.push(context, MaterialPageRoute<void>(builder: (_) => PrivacyPolicyScreen(spanish: es))), icon: const Icon(Icons.privacy_tip_outlined), label: Text(t(context, 'Política de privacidad', 'Privacy policy'))),
              OutlinedButton.icon(onPressed: () => showLicensePage(context: context, applicationName: kAppName, applicationVersion: kAppVersion), icon: const Icon(Icons.description_outlined), label: Text(t(context, 'Licencias de código abierto', 'Open-source licenses'))),
            ],
          ),
        ],
      ),
    );
  }
}

class _Section {
  const _Section(this.icon, this.title, this.body);

  final IconData icon;
  final String title;
  final String body;
}

/// Las secciones de la guía. La de avisos lista los bancos desde
/// [BankRules.bankNames], la misma lista que usa el lector.
List<_Section> _sections(bool es) {
  final String banks = BankRules.namesList(spanish: es);
  if (es) {
    return <_Section>[
      const _Section(Icons.add_circle_outline, 'Anotar un gasto en 5 segundos', 'Toca el botón + : escribe el monto (la calculadora suma, resta, multiplica y divide; si no pulsas =, la operación se resuelve al guardar), elige categoría y listo. La cuenta por defecto es la última que usaste. Si algo se repite (bus, tinto, almuerzo), guárdalo como favorito desde el menú ⋮ del editor y anótalo con un toque desde Inicio.'),
      const _Section(Icons.account_balance_wallet_outlined, 'Cuentas, bolsillos y tarjetas', 'Crea una cuenta por cada sitio donde tengas plata: efectivo, cuenta de ahorros, Nequi, Daviplata, tarjeta de crédito, préstamo, CDT. Los bolsillos cuelgan de una cuenta madre y se suman a ella. Una tarjeta débito se enlaza a su cuenta: lo que pagues con ella se descuenta de la cuenta y aparece en la lista, los presupuestos y los informes de esa cuenta. Si el saldo no cuadra con el del banco, usa "Ajustar saldo real": crea un ajuste que corrige el saldo sin contar como gasto ni ingreso. Al archivar una cuenta se pausan sus programados, y los favoritos que la usaban te piden elegir otra.'),
      const _Section(Icons.credit_card, 'Tarjetas de crédito: un estimado', 'Con el día de corte y el de pago, Plata estima el capital de cada estado de cuenta: las compras y avances del ciclo, las cuotas que caen en él (la primera llega en el primer corte después de la compra), lo que quedó sin pagar del estado anterior y los pagos que hagas hasta la fecha límite. Es capital estimado, sin intereses ni cuota de manejo (ni seguros o comisiones): cada banco los calcula distinto, así que el valor exacto a pagar es el del extracto o la app de tu banco. Al crear una tarjeta que ya usas, anota la deuda total y, si lo sabes, el pago mínimo del último extracto (no el pago total, que es toda la deuda): eso es lo que vence, y si pagas al menos ese mínimo la tarjeta queda al día; el resto queda como «deuda de antes de Plata», que cuenta en la deuda y el cupo pero no se suma al próximo pago. Los avances (sacar plata de la tarjeta) también van a cuotas: Plata propone 24. Plata solo dice «Vencido» cuando conoce el pago mínimo del extracto, porque lo anotaste, y lo que anotaste como pagado después del corte es menos; si solo tiene su estimado, te dice cuánto queda según lo anotado y te deja registrar el pago o anotar el mínimo. Cada vez que anotas un mínimo, Plata pregunta si ya lo pagaste, y «Ya lo pagué» marca ese extracto como pagado y anota un movimiento «Pago hecho fuera de Plata» por exactamente lo que faltaba: no sale de ninguna cuenta ni cuenta como ingreso, y lo ves en Movimientos, donde se edita o se borra (también con «Cambiar monto», «Deshacer» o «Desmarcar» en Tarjetas). Si lo pagaste desde una cuenta que tienes en Plata, regístralo con «Registrar el pago» en la fila de ese extracto: queda asociado a él con cualquier fecha y reemplaza el de fuera. Si lo pagaste desde otra entidad, basta la marca. Si después anotas un abono a la tarjeta (entre la marca y la fecha límite del extracto siguiente, y sin un extracto más nuevo con su mínimo sin pagar), Plata lo cuenta una sola vez y pregunta una vez si es ese pago: enseguida si lo anotas tú (con +, un favorito, «Anotar ahora» o «Duplicar hoy»), y en Inicio si llegó con un programado automático. Mientras no contestes, para la mora cuenta en su propio extracto. Si es otro pago, queda aparte y baja el próximo pago. Si lo anotas más tarde, toca «Ya lo anoté en Plata» en la fila del extracto (los más viejos están en «Ver extractos anteriores pagados fuera de Plata») y elige el movimiento; si te equivocas, toca «Deshacer» enseguida, antes de cambiar otra cosa de la tarjeta. Si el abono que guardas parece ese pago anotado tarde, Plata te lo sugiere una sola vez con un aviso: «¿Es el pago del extracto del…? Elegir». Si la fecha límite cae en sábado, domingo o festivo, se corre al siguiente día hábil, y un pago hasta ese día cuenta para ese extracto. Los ajustes de saldo de una tarjeta van a la deuda aparte, no al próximo pago.'),
      const _Section(Icons.swap_horiz, 'Transferencias y pagos de tarjeta', 'Mover plata entre cuentas (retiro, pasar a Nequi, pagar la tarjeta, abonar al préstamo) es una transferencia: no es gasto ni ingreso. Si las cuentas tienen monedas distintas, Plata calcula cuánto llega con la tasa guardada y puedes corregirlo con lo que de verdad llegó; si no hay tasa para esa moneda, te pide el monto recibido. Lo mismo vale para programados y favoritos.'),
      const _Section(Icons.calendar_month_outlined, 'Quincenas y periodo', 'En Ajustes eliges si tu mes empieza el día 1, el día de pago o si manejas quincenas (1–15 y 16–fin). Inicio e Informes usan ese periodo. Los programados pueden repetirse "quincenal", que cae el 15 y el último día de cada mes.'),
      const _Section(Icons.event_repeat, 'Programados', 'Arriendo, administración, servicios, salario, cuotas: se anotan solos el día que toca (o quedan pendientes si prefieres confirmarlos) y te avisan antes con una notificación. Los recordatorios se reprograman solos cada vez que cambias un programado.'),
      const _Section(Icons.savings_outlined, 'Presupuestos', 'Ponle un tope a una o varias categorías (con sus subcategorías), a todo el gasto, o a una tarjeta. Puedes arrastrar el sobrante al periodo siguiente. Un reembolso (un ingreso anotado en una categoría de gasto) descuenta del gasto; los ajustes de saldo no cuentan. "Ver movimientos" muestra exactamente lo que suma el presupuesto.'),
      _Section(Icons.notifications_active_outlined, 'Avisos bancarios (Android)', 'Si lo activas, Plata lee las notificaciones de estas apps: $banks. Nada sale del teléfono. Te sugiere el movimiento con monto, moneda y comercio, y tú confirmas o descartas. Los pagos de tarjeta, los retiros y lo que pasas entre tus cuentas se sugieren como transferencias y siempre los revisas tú. Para que un aviso caiga en la cuenta correcta, elige el banco de la cuenta y escribe sus últimos 4 dígitos; "Anotar sin preguntar" solo anota gastos e ingresos cuya cuenta se reconoce sin dudas; las compras con tarjeta de crédito siempre se revisan, porque el aviso no dice a cuántas cuotas fueron. Al apagarlo, Plata deja de leer y borra lo que había capturado sin revisar.'),
      const _Section(Icons.currency_exchange, 'Monedas y tasas', 'Plata convierte con la TRM oficial (datos.gov.co) para dólar y peso, con las del Banco Central Europeo (vía Frankfurter) y, para las monedas que el BCE no publica, con ExchangeRate-API (Rates By Exchange Rate API). También puedes escribir una tasa a mano, con todos sus decimales; la tasa manual manda sobre la descargada. Cada movimiento guarda la tasa del día en que se anotó. Si cambias la moneda base, presupuestos y tasas se convierten.'),
      const _Section(Icons.bar_chart_outlined, 'Informes y exportar', 'Informes muestra la dona por categoría (toca una para ver subcategorías y movimientos), la tendencia de los últimos periodos, presupuestos y el flujo por cuenta. Los reembolsos descuentan de su categoría y los ajustes de saldo no cuentan. Exporta CSV o Excel desde el icono de compartir.'),
      const _Section(Icons.lock_outline, 'Seguridad', 'Pon una clave (y huella o rostro) en Seguridad. Con la clave puesta, Plata se tapa al salir de la app: no se ve en las apps recientes y Android no deja tomar capturas de pantalla. Tras varios intentos fallidos hay que esperar, aunque cierres la app. Nadie puede recuperar la clave: si la olvidas, en la pantalla de bloqueo toca "¿Olvidaste la clave?" para borrar todo lo de Plata en este teléfono y empezar de nuevo; luego puedes restaurar una copia.'),
      const _Section(Icons.backup_outlined, 'Copias de seguridad', 'Todo se guarda cifrado en el teléfono, con una llave que no sale de él: por eso las copias de Google o iCloud no llevan los datos de Plata, y desinstalar la app los borra. Haz copias cifradas con contraseña desde Copias de seguridad y guárdalas en tu Drive o correo; con ellas pasas tus datos a un teléfono nuevo. Las copias llevan los movimientos, no las fotos de recibos. Si un día Plata no puede abrir sus datos, no los sobrescribe: te deja restaurar una copia o empezar de cero, y aparta el archivo que no abrió.'),
      const _Section(Icons.search, 'Buscar y filtrar', 'En Movimientos busca por texto o monto y filtra por cuenta, categoría, fechas, montos, etiquetas o adjuntos. El calendario muestra el neto de cada día.'),
    ];
  }
  return <_Section>[
    const _Section(Icons.add_circle_outline, 'Log an expense in 5 seconds', 'Tap + : type the amount (the calculator adds, subtracts, multiplies and divides; if you do not press =, the pending operation is worked out when saving), pick a category and done. The default account is the last one you used. If something repeats, save it as a favorite from the editor ⋮ menu and log it with one tap from Home.'),
    const _Section(Icons.account_balance_wallet_outlined, 'Accounts, pockets and cards', 'Create an account for every place you keep money: cash, savings, wallets, credit card, loan, investments. Pockets hang from a parent account and add to it. A debit card links to its account: what you pay with it is taken from the account and shows up in that account list, budgets and reports. If the balance does not match the bank, use "Adjust real balance": it creates an adjustment that fixes the balance without counting as expense or income. Archiving an account pauses its scheduled items, and favorites that used it ask you to pick another.'),
    const _Section(Icons.credit_card, 'Credit cards: an estimate', 'With the statement and payment days, Plata estimates the principal of each statement: the purchases and cash advances of the cycle, the installments that fall in it (the first one arrives on the first statement after the purchase), whatever was left unpaid from the previous statement, and the payments you make up to the due date. It is estimated principal, without interest or card fees (or insurance and charges): every bank works them out differently, so the exact amount to pay is the one on your bank statement or app. When you add a card you already use, enter the total debt and, if you know it, the minimum payment on the last statement (not the total payment, which is the whole debt): that is what is due, and paying at least that minimum keeps the card up to date; the rest is kept as "debt from before Plata", which counts toward the debt and the limit but is not added to the next payment. Cash advances (taking money out of the card) can also go in installments: Plata suggests 24. Plata only says "Overdue" when it knows the statement minimum payment, because you entered it, and what you logged as paid after the closing date is less; with only its estimate, it tells you how much is left according to what you logged and lets you log the payment or enter the minimum. Every time you enter a minimum, Plata asks whether you already paid it, and "Already paid" marks that statement as paid and logs a "Payment made outside Plata" transaction for exactly what was missing: it does not come from any account or count as income, and it shows up in Transactions, where you can edit or delete it (also with "Change amount", "Undo" or "Unmark" in Cards). If you paid it from an account you have in Plata, log it with "Log the payment" on the row of that statement: it is linked to it whatever its date and replaces the outside one. If you paid it from another institution, the mark is enough. If you later log a payment to the card (between the mark and the due date of the next statement, and with no newer statement whose minimum is unpaid), Plata counts it once and asks once whether it is that payment: right away if you log it yourself (with +, a favorite, "Log now" or "Duplicate today"), and on Home if it arrived with an automatic scheduled payment. Until you answer, it counts for its own statement when checking overdue payments. If it is another payment, it stays separate and lowers the next payment. If you log it later, tap "I already logged it in Plata" on the row of the statement (older ones are under "See earlier statements paid outside Plata") and choose the transaction; if you get it wrong, tap "Undo" right away, before changing anything else on the card. If the payment you save looks like that payment logged late, Plata suggests it once with a notice: "Is it the payment of the … statement? Choose". If the due date falls on a Saturday, Sunday or holiday, it moves to the next business day, and a payment up to that day counts for that statement. Balance adjustments on a card go to the separate debt, not the next payment.'),
    const _Section(Icons.swap_horiz, 'Transfers and card payments', 'Moving money between accounts (withdrawals, paying the card, paying down a loan) is a transfer: neither expense nor income. If the accounts use different currencies, Plata works out what arrives with the saved rate and you can correct it with what really arrived; if there is no rate for that currency, it asks for the amount received. The same goes for scheduled items and favorites.'),
    const _Section(Icons.calendar_month_outlined, 'Twice a month and period', 'In Settings choose whether your month starts on the 1st, on payday, or whether you split it twice a month (1st–15th and 16th–end). Home and Reports use that period. Scheduled items can repeat "twice a month", on the 15th and the last day.'),
    const _Section(Icons.event_repeat, 'Scheduled', 'Rent, utilities, salary, installments: they are logged automatically when due (or wait for confirmation if you prefer) and remind you beforehand with a notification. Reminders are rescheduled every time you change a scheduled item.'),
    const _Section(Icons.savings_outlined, 'Budgets', 'Cap one or more categories (with their subcategories), all spending, or one card. Leftovers can roll over to the next period. A refund (income logged in an expense category) is subtracted from spending; balance adjustments do not count. "See transactions" lists exactly what adds up in the budget.'),
    _Section(Icons.notifications_active_outlined, 'Bank notices (Android)', 'If enabled, Plata reads notifications from these apps: $banks. Nothing leaves the phone. It suggests the transaction with amount, currency and merchant, and you confirm or dismiss. Card payments, withdrawals and moves between your own accounts are suggested as transfers and you always review them. For a notice to land in the right account, choose the account bank and type its last 4 digits; "Log without asking" only logs expenses and income whose account is recognised beyond doubt; credit card purchases are always reviewed, because the notice does not say how many installments they were. Turning it off stops the reading and deletes what was captured but not reviewed.'),
    const _Section(Icons.currency_exchange, 'Currencies and rates', 'Plata converts with the official TRM (datos.gov.co) for dollar and peso, with European Central Bank rates (via Frankfurter) and, for currencies the ECB does not publish, with ExchangeRate-API (Rates By Exchange Rate API). You can also type a rate by hand, with all its decimals; a manual rate wins over the downloaded one. Each transaction keeps the rate of the day it was logged. If you change the base currency, budgets and rates are converted.'),
    const _Section(Icons.bar_chart_outlined, 'Reports and export', 'Reports shows the category donut (tap one for subcategories and transactions), the trend over recent periods, budgets and cash flow per account. Refunds are subtracted from their category and balance adjustments do not count. Export CSV or Excel from the share icon.'),
    const _Section(Icons.lock_outline, 'Security', 'Set a passcode (and fingerprint or face) under Security. With a passcode, Plata covers itself when you leave the app: it does not show in recent apps and Android blocks screenshots. After several failed attempts you have to wait, even if you close the app. Nobody can recover the passcode: if you forget it, tap "Forgot the passcode?" on the lock screen to erase everything Plata keeps on this phone and start over; then you can restore a backup.'),
    const _Section(Icons.backup_outlined, 'Backups', 'Everything is stored encrypted on the phone with a key that never leaves it, so Google or iCloud backups do not carry Plata data, and uninstalling the app deletes it. Make password-protected backups from Backups and keep them in your Drive or email; they are how you move your data to a new phone. Backups carry the transactions, not receipt photos. If Plata ever cannot open its data, it does not overwrite it: it lets you restore a backup or start from scratch, and sets aside the file it could not open.'),
    const _Section(Icons.search, 'Search and filter', 'In Transactions search by text or amount and filter by account, category, dates, amounts, tags or attachments. The calendar shows the net of each day.'),
  ];
}
